21875 32.328125 \nQ 11.53125 32.328125 10.9375 33.109375 \nQ 10.359375 33.890625 10.359375 34.28125 \nQ 10.640625 35.9375 13.953125 39.203125 \nQ 17.28125 42.484375 20.3125 42.484375 \nz\n\" id=\"CrimsonText-Italic-120\"></path>\n     </defs>\n     <g transform=\"translate(253.111793 244.798528)scale(0.15 -0.15)\">\n      <use xlink:href=\"#CrimsonText-Italic-120\"></use>\n     </g>\n    </g>\n   </g>\n   <g id=\"line2d_1\">\n    <defs>\n     <path d=\"M 0 3 \nC 0.795609 3 1.55874 2.683901 2.12132 2.12132 \nC 2.683901 1.55874 3 0.795609 3 0 \nC 3 -0.795609 2.683901 -1.55874 2.12132 -2.12132 \nC 1.55874 -2.683901 0.795609 -3 0 -3 \nC -0.795609 -3 -1.55874 -2.683901 -2.12132 -2.12132 \nC -2.683901 -1.55874 -3 -0.795609 -3 0 \nC -3 0.795609 -2.683901 1.55874 -2.12132 2.12132 \nC -1.55874 2.683901 -0.795609 3 0 3 \nz\n\" id=\"m1709572b5e\" style=\"stroke:#000000;\"></path>\n    </defs>\n    <g clip-path=\"url(#p071db4904a)\">\n     <use style=\"stroke:#000000;\" x=\"38.700427\" xlink:href=\"#m1709572b5e\" y=\"241.503216\"></use>\n     <use style=\"stroke:#000000;\" x=\"79.145475\" xlink:href=\"#m1709572b5e\" y=\"217.236187\"></use>\n     <use style=\"stroke:#000000;\" x=\"119.590522\" xlink:href=\"#m1709572b5e\" y=\"184.880149\"></use>\n     <use style=\"stroke:#000000;\" x=\"160.03557\" xlink:href=\"#m1709572b5e\" y=\"156.568616\"></use>\n     <use style=\"stroke:#000000;\" x=\"200.480617\" xlink:href=\"#m1709572b5e\" y=\"160.613121\"></use>\n     <use style=\"stroke:#000000;\" x=\"240.925665\" xlink:href=\"#m1709572b5e\" y=\"156.568616\"></use>\n    </g>\n   </g>\n   <g id=\"line2d_2\">\n    <path clip-path=\"url(#p071db4904a)\" d=\"M 38.700427 230.71787 \nL 240.925665 141.738765 \nL 240.925665 141.738765 \n\" style=\"fill:none;stroke:#000000;stroke-linecap:square;stroke-width:2.3;\"></path>\n   </g>\n  </g>\n </g>\n <defs>\n  <clipPath id=\"p071db4904a\">\n   <rect height=\"260.82\" width=\"255.536866\" x=\"12.676567\" y=\"7.2\"></rect>\n  </clipPath>\n </defs>\n</svg>\n<div role=\"region\" aria-label=\"Long description for scatterplot\" class=\"sr-only\"><ul>\n<li>The scatterplot has 6 data points.</li>\n<li>The data points are in a linear pattern trending up from left to right.</li>\n<li>A line of best fit is shown:\n<ul>\n<li>The line of best fit slants up from left to right.</li>\n<li>1 point is touching the line of best fit.</li>\n<li>2 points are above the line of best fit.</li>\n<li>3 points are below the lines of best fit.</li>\n<li>The line of best fit passes through the following approximate coordinates:\n<ul>\n<li>(0 comma 0.2)</li>\n<li>(4 comma 2)</li>\n</ul>\n</li>\n</ul>\n</li>\n</ul></div></figure></p>\n<p style=\"text-align: left;\">Which of the following is closest to the slope of the line of best fit shown?</p>","answerOptions":[{"id":"a858d69c-057b-4af8-a073-e0bc257ae56d","content":"<p><math alttext=\"negative 2.27\"><mo>-</mo><mn>2.27</mn>\n</math></p>"},{"id":"ff3a8903-bb4c-4dc8-bb71-bcb146e2ee1a","content":"<p><math alttext=\"negative 0.44\"><mo>-</mo><mn>0.44</mn>\n</math></p>"},{"id":"65d850af-12ec-47f0-96cb-054458ab5c0c","content":"<p><math alttext=\"0.44\"><mn>0.44</mn>\n</math></p>"},{"id":"dea4b1b8-0a67-48fd-9ce7-ad2d260a8f12","content":"<p><math alttext=\"2.27\"><mn>2.27</mn>\n</math></p>"}],"keys":["65d850af-12ec-47f0-96cb-054458ab5c0c"],"correct_answer":["C"],"rationale":"<p style=\"text-align: left;\">Choice C is correct. It's given that the scatterplot shows the relationship between two variables, <math alttext=\"x\"><mi>x</mi>\n</math> and <math alttext=\"y\"><mi>y</mi>\n</math>, and a line of best fit is shown. For the line of best fit shown, for each increase in the value of <math alttext=\"x\"><mi>x</mi>\n</math> by <math alttext=\"1\"><mn>1</mn>\n</math>, the corresponding value of <math alttext=\"y\"><mi>y</mi>\n</math> increases by a constant rate. It follows that the relationship between the variables <math alttext=\"x\"><mi>x</mi>\n</math> and <math alttext=\"y\"><mi>y</mi>\n</math> has a positive linear trend. A line in the <em>xy</em>-plane that passes through the points&nbsp;<math alttext=\"left parenthesis a comma b right parenthesis\"><mfenced><mrow><mi>a</mi><mo>,</mo><mi>b</mi></mrow></mfenced></math> and&nbsp;<math alttext=\"left parenthesis c comma d right parenthesis\"><mfenced><mrow><mi>c</mi><mo>,</mo><mi>d</mi></mrow></mfenced></math> has a slope of&nbsp;<math alttext=\"StartFraction d minus b Over c minus a EndFraction\"><mfrac><mrow><mi>d</mi><mo>-</mo><mi>b</mi></mrow><mrow><mi>c</mi><mo>-</mo><mi>a</mi></mrow></mfrac></math>. The line of best fit shown passes approximately through the points <math alttext=\"left parenthesis 0 comma 0.25 right parenthesis\"><mfenced><mrow><mn>0</mn><mo>,</mo><mn>0.25</mn></mrow></mfenced></math> and&nbsp;<math alttext=\"left parenthesis 4 comma 2 right parenthesis\"><mfenced><mrow><mn>4</mn><mo>,</mo><mn>2</mn></mrow></mfenced></math>. It follows that the slope of this line is approximately <math alttext=\"StartFraction 2 minus 0.25 Over 4 minus 0 EndFraction\"><mfrac><mrow><mn>2</mn><mo>-</mo><mn>0.25</mn></mrow><mrow><mn>4</mn><mo>-</mo><mn>0</mn></mrow></mfrac></math>, which is equivalent to <math alttext=\"0.4375\"><mn>0.4375</mn>\n</math>. Therefore, of the given choices, <math alttext=\"0.44\"><mn>0.44</mn>\n</math> is closest to the slope of the line of best fit shown.</p>\n<p style=\"text-align: left;\">Choice A is incorrect. This is the slope of a line of best fit for a relationship between <math alttext=\"x\"><mi>x</mi>\n</math> and <math alttext=\"y\"><mi>y</mi>\n</math> that has a negative, rather than a positive, linear trend.</p>\n<p style=\"text-align: left;\">Choice B is incorrect. This is the slope of a line of best fit for a relationship between <math alttext=\"x\"><mi>x</mi>\n</math> and <math alttext=\"y\"><mi>y</mi>\n</math> that has a negative, rather than a positive, linear trend.</p>\n<p style=\"text-align: left;\">Choice D is incorrect and may result from conceptual or calculation errors.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":"manifold","position":null,"image_count":0,"raw_list":{"updateDate":1691007959834,"pPcc":"SAT#Q","questionId":"39aa146d","skill_cd":"Q.D.","score_band_range_cd":2,"skill_desc":"Two-variable data: Models and scatterplots","createDate":1691007959834,"program":"SAT","primary_class_cd_desc":"Problem-Solving and Data Analysis","ibn":null,"external_id":"62f651c4-37e7-4fa9-8a3d-ff62ceb23066","primary_class_cd":"Q","uId":"f0292b5f-3705-4a8e-bb65-76b8efa19f66","difficulty":"E"},"raw_detail":{"keys":["65d850af-12ec-47f0-96cb-054458ab5c0c"],"rationale":"<p style=\"text-align: left;\">Choice C is correct. It's given that the scatterplot shows the relationship between two variables, <math alttext=\"x\"><mi>x</mi>\n</math> and <math alttext=\"y\"><mi>y</mi>\n</math>, and a line of best fit is shown. For the line of best fit shown, for each increase in the value of <math alttext=\"x\"><mi>x</mi>\n</math> by <math alttext=\"1\"><mn>1</mn>\n</math>, the corresponding value of <math alttext=\"y\"><mi>y</mi>\n</math> increases by a constant rate. It follows that the relationship between the variables <math alttext=\"x\"><mi>x</mi>\n</math> and <math alttext=\"y\"><mi>y</mi>\n</math> has a positive linear trend. A line in the <em>xy</em>-plane that passes through the points&nbsp;<math alttext=\"left parenthesis a comma b right parenthesis\"><mfenced><mrow><mi>a</mi><mo>,</mo><mi>b</mi></mrow></mfenced></math> and&nbsp;<math alttext=\"left parenthesis c comma d right parenthesis\"><mfenced><mrow><mi>c</mi><mo>,</mo><mi>d</mi></mrow></mfenced></math> has a slope of&nbsp;<math alttext=\"StartFraction d minus b Over c minus a EndFraction\"><mfrac><mrow><mi>d</mi><mo>-</mo><mi>b</mi></mrow><mrow><mi>c</mi><mo>-</mo><mi>a</mi></mrow></mfrac></math>. The line of best fit shown passes approximately through the points <math alttext=\"left parenthesis 0 comma 0.25 right parenthesis\"><mfenced><mrow><mn>0</mn><mo>,</mo><mn>0.25</mn></mrow></mfenced></math> and&nbsp;<math alttext=\"left parenthesis 4 comma 2 right parenthesis\"><mfenced><mrow><mn>4</mn><mo>,</mo><mn>2</mn></mrow></mfenced></math>. It follows that the slope of this line is approximately <math alttext=\"StartFraction 2 minus 0.25 Over 4 minus 0 EndFraction\"><mfrac><mrow><mn>2</mn><mo>-</mo><mn>0.25</mn></mrow><mrow><mn>4</mn><mo>-</mo><mn>0</mn></mrow></mfrac></math>, which is equivalent to <math alttext=\"0.4375\"><mn>0.4375</mn>\n</math>. Therefore, of the given choices, <math alttext=\"0.44\"><mn>0.44</mn>\n</math> is closest to the slope of the line of best fit shown.</p>\n<p style=\"text-align: left;\">Choice A is incorrect. This is the slope of a line of best fit for a relationship between <math alttext=\"x\"><mi>x</mi>\n</math> and <math alttext=\"y\"><mi>y</mi>\n</math> that has a negative, rather than a positive, linear trend.</p>\n<p style=\"text-align: left;\">Choice B is incorrect. This is the slope of a line of best fit for a relationship between <math alttext=\"x\"><mi>x</mi>\n</math> and <math alttext=\"y\"><mi>y</mi>\n</math> that has a negative, rather than a positive, linear trend.</p>\n<p style=\"text-align: left;\">Choice D is incorrect and may result from conceptual or calculation errors.</p>","origin":"manifold","stem":"<p style=\"text-align: left;\">The scatterplot shows the relationship between <math alttext=\"x\"><mi>x</mi>\n</math> and <math alttext=\"y\"><mi>y</mi>\n</math>. A line of best fit is also shown.</p>\n<p style=\"text-align: center;\"><figure class='image'><svg height=\"275.22pt\" version=\"1.1\" viewBox=\"0 0 286.56 275.22\" width=\"286.56pt\" xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\" role=\"img\" aria-label=\"A scatterplot in the x y plane with the origin labeled O. The x axis ranges from 0 to 5 in increments of 1. The y axis ranges from 0 to 5 in increments of 1. Refer to long descr